/**
 * Updates the project-scoped review marks without sending or changing a draft.
 * @summary Set one client's Mail review marks
 */
export const setClientMarks = async (id: number,
    clientMarksBody: ClientMarksBody, options?: Parameters<typeof hubMutator>[1]): Promise<setClientMarksResponse> => {

  return hubMutator<setClientMarksResponse>(getSetClientMarksUrl(id),
  {
    ...options,
    method: 'PUT',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(clientMarksBody)
  }
);}


export type createManualMailDraftResponse200 = {
  data: DraftChanged
  status: 200
}

export type createManualMailDraftResponse400 = {
  data: ApiErrorResponse
  status: 400
}

export type createManualMailDraftResponse403 = {
  data: ApiErrorResponse
  status: 403
}

export type createManualMailDraftResponse404 = {
  data: ApiErrorResponse
  status: 404
}

export type createManualMailDraftResponse409 = {
  data: ApiErrorResponse
  status: 409
}

export type createManualMailDraftResponse503 = {
  data: ApiErrorResponse
  status: 503
}

export type createManualMailDraftResponseSuccess = (createManualMailDraftResponse200) & {
  headers: Headers;
};
export type createManualMailDraftResponseError = (createManualMailDraftResponse400 | createManualMailDraftResponse403 | createManualMailDraftResponse404 | createManualMailDraftResponse409 | createManualMailDraftResponse503) & {
  headers: Headers;
};

export type createManualMailDraftResponse = (createManualMailDraftResponseSuccess | createManualMailDraftResponseError)

export const getCreateManualMailDraftUrl = (slug: string,
    id: number,) => {




  return `/api/projects/${encodeURIComponent(String(slug))}/clients/${encodeURIComponent(String(id))}/draft`
}

/**
 * Creates a draft only. It never sends a message.
 * @summary Create one unsent owner-authored Mail draft
 */
export const createManualMailDraft = async (slug: string,
    id: number,
    manualReplyBody: ManualReplyBody, options?: Parameters<typeof hubMutator>[1]): Promise<createManualMailDraftResponse> => {

  return hubMutator<createManualMailDraftResponse>(getCreateManualMailDraftUrl(slug,id),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(manualReplyBody)
  }
);}


